import { randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const dataFile = path.join(process.cwd(), "data", "books.json");

async function readBooks() {
  try {
    const raw = await readFile(dataFile, "utf8");
    const books = JSON.parse(raw);
    return Array.isArray(books) ? books : [];
  } catch (error) {
    if (error.code === "ENOENT") return [];
    throw error;
  }
}

async function writeBooks(books) {
  await mkdir(path.dirname(dataFile), { recursive: true });
  await writeFile(dataFile, JSON.stringify(books, null, 2) + "\n");
}

export async function listBooks() {
  const books = await readBooks();
  return books.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

export async function getBook(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const trimmedTitle = String(title ?? "").trim();
  const trimmedAuthor = String(author ?? "").trim();
  const trimmedNotes = String(notes ?? "").trim();
  if (!trimmedTitle || !trimmedAuthor) {
    const error = new Error("Title and author are required");
    error.status = 400;
    throw error;
  }

  const now = new Date().toISOString();
  const book = {
    id: randomUUID(),
    title: trimmedTitle,
    author: trimmedAuthor,
    notes: trimmedNotes,
    status: "reading",
    createdAt: now,
    updatedAt: now,
  };
  const books = await readBooks();
  books.push(book);
  await writeBooks(books);
  return book;
}

export async function finishBook(id) {
  const books = await readBooks();
  const book = books.find((item) => item.id === id);
  if (!book) return null;
  book.status = "finished";
  book.updatedAt = new Date().toISOString();
  await writeBooks(books);
  return book;
}

import { createServer } from "node:http";
import { addBook, finishBook, getBook, listBooks } from "./store.js";

const port = Number(process.env.PORT) || 3000;

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { font-family: Georgia, serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #1c1917; background: #faf7f2; }
    h1, h2 { font-weight: normal; }
    a { color: #9a3412; }
    form, .card { background: #fff; border: 1px solid #e7e5e4; border-radius: 8px; padding: 1rem; margin: 1rem 0; }
    label { display: block; margin-top: 0.75rem; }
    input, textarea { width: 100%; box-sizing: border-box; font: inherit; padding: 0.4rem; margin-top: 0.25rem; }
    button { font: inherit; margin-top: 0.75rem; padding: 0.4rem 0.8rem; cursor: pointer; }
    ul { list-style: none; padding: 0; }
    li { margin: 0.4rem 0; }
    .muted { color: #78716c; }
    .empty { color: #78716c; font-style: italic; }
  </style>
</head>
<body>
  <p><a href="/">Books</a></p>
  ${body}
</body>
</html>`;
}

function bookItem(book) {
  return `<li>
    <a href="/books/${book.id}">${escapeHtml(book.title)}</a>
    <span class="muted">by ${escapeHtml(book.author)}</span>
  </li>`;
}

function homePage(books) {
  const reading = books.filter((book) => book.status === "reading");
  const finished = books.filter((book) => book.status === "finished");
  const list = (items) =>
    items.length ? `<ul>${items.map(bookItem).join("")}</ul>` : `<p class="empty">None yet.</p>`;

  return layout(
    "Books",
    `<h1>Books</h1>
    <section>
      <h2>Currently reading</h2>
      ${list(reading)}
    </section>
    <section>
      <h2>Finished</h2>
      ${list(finished)}
    </section>
    <form method="post" action="/books">
      <h2>Add a book</h2>
      <label>Title <input name="title" required></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" rows="4"></textarea></label>
      <button type="submit">Add book</button>
    </form>`
  );
}

function bookPage(book) {
  const finishForm =
    book.status === "reading"
      ? `<form method="post" action="/books/${book.id}/finish"><button type="submit">Mark as finished</button></form>`
      : `<p class="muted">Finished</p>`;

  return layout(
    book.title,
    `<h1>${escapeHtml(book.title)}</h1>
    <p>by ${escapeHtml(book.author)}</p>
    ${finishForm}
    <section class="card">
      <h2>Notes</h2>
      <p>${book.notes ? escapeHtml(book.notes).replaceAll("\n", "<br>") : '<span class="empty">No notes yet.</span>'}</p>
    </section>`
  );
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => {
      const params = new URLSearchParams(Buffer.concat(chunks).toString());
      resolve(Object.fromEntries(params));
    });
    req.on("error", reject);
  });
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
  const bookMatch = url.pathname.match(/^\/books\/([^/]+)$/);
  const finishMatch = url.pathname.match(/^\/books\/([^/]+)\/finish$/);

  try {
    if (req.method === "GET" && url.pathname === "/") {
      send(res, 200, homePage(await listBooks()));
      return;
    }

    if (req.method === "POST" && url.pathname === "/books") {
      const body = await parseBody(req);
      const book = await addBook(body);
      redirect(res, `/books/${book.id}`);
      return;
    }

    if (req.method === "GET" && bookMatch) {
      const book = await getBook(bookMatch[1]);
      if (!book) {
        send(res, 404, layout("Not found", "<h1>Book not found</h1>"));
        return;
      }
      send(res, 200, bookPage(book));
      return;
    }

    if (req.method === "POST" && finishMatch) {
      const book = await finishBook(finishMatch[1]);
      if (!book) {
        send(res, 404, layout("Not found", "<h1>Book not found</h1>"));
        return;
      }
      redirect(res, `/books/${book.id}`);
      return;
    }

    send(res, 404, layout("Not found", "<h1>Not found</h1>"));
  } catch (error) {
    const status = error.status || 500;
    send(res, status, layout("Error", `<h1>${escapeHtml(error.message)}</h1>`));
  }
});

server.listen(port, () => {
  console.log(`Books app listening on http://localhost:${port}`);
});

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

describe("book store", () => {
  let dir;

  beforeEach(async () => {
    dir = await mkdtemp(path.join(os.tmpdir(), "books-"));
    vi.resetModules();
    vi.spyOn(process, "cwd").mockReturnValue(dir);
    await writeFile(path.join(dir, "package.json"), "{}");
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await rm(dir, { recursive: true, force: true });
  });

  it("adds a book and lists it as currently reading", async () => {
    const store = await import("./store.js");
    const book = await store.addBook({
      title: "  The Left Hand of Darkness  ",
      author: "Ursula K. Le Guin",
      notes: "Cold and kind.",
    });

    expect(book.status).toBe("reading");
    const books = await store.listBooks();
    expect(books).toHaveLength(1);
    expect(books[0].title).toBe("The Left Hand of Darkness");

    const saved = JSON.parse(await readFile(path.join(dir, "data", "books.json"), "utf8"));
    expect(saved[0].id).toBe(book.id);
  });

  it("marks a book finished and keeps it after a fresh read", async () => {
    const store = await import("./store.js");
    const book = await store.addBook({ title: "Kindred", author: "Octavia Butler", notes: "" });
    const finished = await store.finishBook(book.id);
    expect(finished.status).toBe("finished");

    vi.resetModules();
    const reloaded = await import("./store.js");
    const again = await reloaded.getBook(book.id);
    expect(again.status).toBe("finished");
    expect(again.author).toBe("Octavia Butler");
  });

  it("rejects a book without a title", async () => {
    const store = await import("./store.js");
    await expect(store.addBook({ title: "  ", author: "Someone" })).rejects.toThrow(/title/i);
  });
});

